    assert!(info.contains("\"rawLength\":84,\"rawHex\":\"00000000000100000000000000000027"));
    assert!(info.contains("\"u16Fields\":[0,0,1,0,0,0,0,39,0,0,370,0"));
    assert!(info.contains("\"u16FieldsHex\":[\"0x0000\",\"0x0000\",\"0x0001\",\"0x0000\""));
